def flood_fill_8connect(grid, seeds):
    """8-connected flood fill"""
    n = len(grid)
    m = len(grid[0])
    working = [[grid[r][c] for c in range(m)] for r in range(n)]

    from collections import deque
    queue = deque(seeds)
    visited = set(seeds)

    while queue:
        r, c = queue.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if (nr, nc) not in visited and grid[nr][nc] == 0:
                        working[nr][nc] = 4
                        visited.add((nr, nc))
                        queue.append((nr, nc))

    return working

